const raw = $input.first().json;
if (!raw || !Array.isArray(raw)) return [];
return raw
  .filter(j => j && j.position)
  .map(j => ({
    json: {
      source: 'RemoteOK',
      job_title: j.position || '',
      company: j.company || '',
      job_url: j.url || `https://remoteok.com/jobs/${j.id}`,
      location_text: j.location || 'Worldwide',
      salary: j.salary_min ? `$${j.salary_min}-$${j.salary_max}/yr` : '',
      description: (j.description || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 3000),
      posted_date: j.date || new Date().toISOString(),
      tags: Array.isArray(j.tags) ? j.tags.join(', ') : '',
      date_found: new Date().toISOString()
    }
  }));

const raw = $input.first().json;
const jobs = raw?.jobs || raw || [];
if (!Array.isArray(jobs)) return [];
return jobs.map(j => ({
  json: {
    source: 'Remotive',
    job_title: j.title || '',
    company: j.company_name || '',
    job_url: j.url || '',
    location_text: j.candidate_required_location || 'Worldwide',
    salary: j.salary || '',
    description: (j.description || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 3000),
    posted_date: j.publication_date || new Date().toISOString(),
    tags: Array.isArray(j.tags) ? j.tags.join(', ') : (j.job_type || ''),
    date_found: new Date().toISOString()
  }
}));

return $input.all().map(item => {
  const j = item.json;
  const title = (j.title || '').replace(/^.*?:\s*/, '');
  return {
    json: {
      source: 'WeWorkRemotely',
      job_title: title,
      company: j.author || '',
      job_url: j.link || '',
      location_text: 'Remote',
      salary: '',
      description: (j.content || j.contentSnippet || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 3000),
      posted_date: j.pubDate || new Date().toISOString(),
      tags: j.categories ? (Array.isArray(j.categories) ? j.categories.join(', ') : j.categories) : '',
      date_found: new Date().toISOString()
    }
  };
});

return $input.all().map(item => {
  const j = item.json;
  return {
