return $input.all().map(item => {
  const j = item.json;
  return {
    json: {
      source: 'DynamiteJobs',
      job_title: j.title || '',
      company: j.author || '',
      job_url: j.link || '',
      location_text: 'Remote',
      salary: '',
      description: (j.content || j.contentSnippet || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 3000),
      posted_date: j.pubDate || new Date().toISOString(),
      tags: '',
      date_found: new Date().toISOString()
    }
  };
});

const html = ($input.first().json?.body || $input.first().json?.data || '').toString();
const jobs = [];
// Parse job cards from Wellfound HTML
const cardPattern = /data-test="StartupResult"[^>]*>[\s\S]*?(?=data-test="StartupResult"|<\/section)/g;
const titlePattern = /class="[^"]*title[^"]*"[^>]*>([^<]+)/i;
const linkPattern = /href="(\/jobs\/[^"]+)"/;
const companyPattern = /class="[^"]*company[^"]*"[^>]*>([^<]+)/i;
const matches = html.match(cardPattern) || [];
for (const card of matches.slice(0, 30)) {
  const titleMatch = card.match(titlePattern);
  const linkMatch = card.match(linkPattern);
  const companyMatch = card.match(companyPattern);
  if (titleMatch && linkMatch) {
    jobs.push({
      json: {
        source: 'Wellfound',
        job_title: titleMatch[1].trim(),
        company: companyMatch ? companyMatch[1].trim() : 'Unknown',
        job_url: `https://wellfound.com${linkMatch[1]}`,
        location_text: 'Remote',
        salary: '',
        description: card.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 3000),
        posted_date: new Date().toISOString(),
        tags: 'startup',
        date_found: new Date().toISOString()
      }
    });
  }
}
return jobs.length > 0 ? jobs : [{ json: { source: 'Wellfound', job_title: '', company: '', job_url: '', location_text: '', salary: '', description: 'no_results', posted_date: new Date().toISOString(), tags: '', date_found: new Date().toISOString() } }];

const html = ($input.first().json?.body || $input.first().json?.data || '').toString();
const jobs = [];
const jobPattern = /<a[^>]*href="(\/jobs\/[^"]+)"[^>]*>[\s\S]*?<\/a>/g;
const titlePattern = /<span[^>]*class="[^"]*title[^"]*"[^>]*>([^<]+)<\/span>/i;
const companyPattern = /<span[^>]*class="[^"]*company[^"]*"[^>]*>([^<]+)<\/span>/i;
const sections = html.split('class="job-name"').slice(1, 31);
for (const section of sections) {
  const titleMatch = section.match(/^[^<]*([^<]{3,80})/);
  const linkMatch = section.match(/href="(\/jobs\/[^"]+)"/);
  const compMatch = section.match(/class="company-name"[^>]*>([^<]+)/);
  if (titleMatch) {
    jobs.push({
      json: {
        source: 'YC Work at a Startup',
        job_title: titleMatch[1].trim(),
        company: compMatch ? compMatch[1].trim() : 'YC Startup',
        job_url: linkMatch ? `https://www.workatastartup.com${linkMatch[1]}` : 'https://www.workatastartup.com/jobs',
        location_text: 'Remote',
        salary: '',
        description: section.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 3000),
        posted_date: new Date().toISOString(),
        tags: 'startup, yc',
        date_found: new Date().toISOString()
      }
    });
  }
}
return jobs.length > 0 ? jobs : [];

const raw = $input.first().json;
const edges = raw?.data?.jobs?.edges || [];
return edges.map(edge => {
  const j = edge?.node || {};
  const salary = j.salaryRange ? `${j.salaryRange.currency || '$'}${j.salaryRange.minSalary || ''}-${j.salaryRange.maxSalary || ''}/yr` : '';
  return {
    json: {
      source: 'Otta',
      job_title: j.title || '',
      company: j.company?.name || '',
      job_url: j.externalUrl || '',
      location_text: (j.locations || []).map(l => l.name).join(', ') || 'Remote',
      salary,
      description: (j.description || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 3000),
      posted_date: new Date().toISOString(),
      tags: (j.skills || []).map(s => s.value).join(', '),
      date_found: new Date().toISOString()
    }
  };
});

const all = $input.all();
const jobSearchKeywords = [
  /data analyst/i, /data scientist/i, /business intelligence/i, /\bbi analyst\b/i,
  /marketing analyst/i, /growth analyst/i, /performance marketing/i,
  /ai marketing/i, /ai automation/i, /ai workflow/i, /automation specialist/i,
  /martech/i, /marketing data/i, /creative strategist/i, /analytics/i
];
const filtered = all
  .filter(item => {
    const j = item.json;
    if (!j.job_title || !j.job_url || j.description === 'no_results') return false;
    const text = `${j.job_title} ${j.description} ${j.tags}`.toLowerCase();
    return jobSearchKeywords.some(kw => kw.test(text));
  })
  .map(item => {
    const j = item.json;
    const jobId = j.job_url || `${j.company}__${j.job_title}`;
    return {
      json: {
        ...j,
        job_id: jobId.replace(/[^a-zA-Z0-9_-]/g, '_').slice(0, 200)
      }
    };
  });
return filtered;

const newJobs = $input.all();
const existingData = $('Get Existing Job URLs').all();
const existingUrls = new Set(existingData.map(item => (item.json.job_url || '').trim().toLowerCase()));
const existingKeys = new Set(existingData.map(item => `${(item.json.company||'').toLowerCase()}__${(item.json.job_title||'').toLowerCase()}`));
const seenUrls = new Set();
const seenKeys = new Set();
const unique = [];
for (const item of newJobs) {
  const url = (item.json.job_url || '').trim().toLowerCase();
  const key = `${(item.json.company||'').toLowerCase()}__${(item.json.job_title||'').toLowerCase()}`;
  if (!url || existingUrls.has(url) || seenUrls.has(url)) continue;
  if (existingKeys.has(key) || seenKeys.has(key)) continue;
  seenUrls.add(url);
  seenKeys.add(key);
  unique.push(item);
}
return unique;

const REJECT = [
  /\bus[\s-]only\b/i, /united states only/i, /\busa only\b/i,
  /\bcanada only\b/i, /\buk[\s-]only\b/i, /\beurope only\b/i,
  /\beu[\s-]only\b/i, /\baustralia only\b/i, /\banz only\b/i,
  /must be (based|located|residing) in/i,
  /must live in/i,
  /must be authorized to work in/i,
  /eligible to work in the (us|uk|eu|canada|australia)/i,
  /local work permit required/i,
  /work (permit|authorization) required/i,
  /\bhybrid\b/i,
  /\bonsite\b/i, /\bon-site\b/i, /\bin-office\b/i,
  /office required/i, /office-based/i,
  /remote (within|in) (us|uk|europe|eu|canada|australia|the us|the uk)/i,
  /us[\s-]based remote/i,
  /fixed (us|est|pst|cet|gmt) hours/i,
  /US timezone required/i
];

const kept = [];
const rejected = [];

for (const item of $input.all()) {
  const j = item.json;
  const text = `${j.location_text} ${j.description} ${j.tags} ${j.job_title}`;
  const reason = REJECT.find(r => r.test(text));
  if (reason) {
    rejected.push({ json: { ...j, rejection_reason: `hard_filter: ${reason.source}`, decision: 'reject' } });
  } else {
    kept.push(item);
  }
}

return [kept, rejected];

return $input.all().map((item, idx) => {
  const prevItems = $('Hard Taiwan Filter').all()[idx]?.json || {};
  const aiRaw = item.json?.content?.[0]?.text || '{}';
  let ai = {};
  try {
    const jsonMatch = aiRaw.match(/\{[\s\S]*\}/);
    ai = JSON.parse(jsonMatch ? jsonMatch[0] : aiRaw);
  } catch(e) {
    ai = { taiwan_eligible: 'unclear', reason: 'parse error', location_risk: 'medium', timezone_risk: 'medium', contractor_possible: 'unclear', decision: 'manual_check' };
  }
  return {
    json: {
      ...prevItems,
      taiwan_eligible: ai.taiwan_eligible || 'unclear',
      taiwan_reason: ai.reason || '',
      location_risk: ai.location_risk || 'medium',
      timezone_risk: ai.timezone_risk || 'medium',
      contractor_possible: ai.contractor_possible || 'unclear',
      ai_decision: ai.decision || 'manual_check'
    }
  };
}).filter(item => item.json.ai_decision !== 'reject');

// ── Async signals ──────────────────────────────────────────────
const ASYNC_KEEP = [/\basync\b/i, /asynchronous/i, /flexible hours/i, /flexible schedule/i, /distributed team/i, /remote.?first/i, /low meeting/i, /work across time zones/i, /no required (overlap|sync)/i, /your own schedule/i];
const ASYNC_REJECT = [/strict 9.?to.?5/i, /fixed (us|est|pst|cet|gmt) hours/i, /daily live calls required/i, /must overlap full (us|eu) business day/i];

// ── Role categories ────────────────────────────────────────────
const ROLE_CATS = {
  data_analytics: [/data analyst/i, /data scientist/i, /junior data scientist/i, /business intelligence/i, /\bbi analyst\b/i, /analytics engineer/i],
  ai_automation: [/ai (marketing|automation|workflow)/i, /automation specialist/i, /ai workflow/i, /llm/i, /machine learning/i],
  marketing_analytics: [/marketing analyst/i, /performance marketing analyst/i, /growth analyst/i, /martech/i, /ga4/i, /sem analyst/i],
  creative_data: [/creative strategist/i, /content analyst/i]
};

function getSalaryNum(salary) {
  if (!salary) return 0;
  const nums = (salary.match(/[\d,]+/g) || []).map(n => parseInt(n.replace(/,/g,''),10)).filter(n => n > 100);
  if (!nums.length) return 0;
  return Math.max(...nums) > 10000 ? Math.max(...nums) / 12 : Math.max(...nums);
}

return $input.all().map(item => {
  const j = item.json;
  const text = `${j.job_title} ${j.description} ${j.tags} ${j.location_text}`;

  // Async scoring
  const asyncSignals = ASYNC_KEEP.filter(p => p.test(text));
  const asyncBlocked = ASYNC_REJECT.some(p => p.test(text));
  let asyncLevel = 'unknown';
  let asyncScore = 0;
  if (!asyncBlocked) {
    if (asyncSignals.length >= 3) { asyncLevel = 'high'; asyncScore = 25; }
    else if (asyncSignals.length >= 1) { asyncLevel = 'medium'; asyncScore = 20; }
    else if (/remote/i.test(text)) { asyncLevel = 'low'; asyncScore = 10; }
    else { asyncLevel = 'unclear'; asyncScore = 5; }
  } else {
    asyncLevel = 'incompatible'; asyncScore = 0;
  }

  // Role scoring
  let roleCategory = 'other';
  let roleScore = 0;
  for (const [cat, patterns] of Object.entries(ROLE_CATS)) {
    if (patterns.some(p => p.test(text))) { roleCategory = cat; roleScore = 25; break; }
  }
  if (roleCategory === 'other' && /analyst|data|marketing|growth|automation/i.test(text)) {
    roleCategory = 'adjacent'; roleScore = 15;
  }

  // Taiwan eligibility scoring
  let taiwanScore = 0;
  const eligible = j.taiwan_eligible;
  if (eligible === 'yes') {
    if (/worldwide|work from anywhere|global remote|contractor|deel|remote\.com|oyster|eor/i.test(text)) taiwanScore = 40;
    else if (/apac|asia/i.test(text)) taiwanScore = 30;
    else taiwanScore = 20;
  } else if (eligible === 'unclear') {
    taiwanScore = 20;
  }

  // Salary scoring
  const salaryNum = getSalaryNum(j.salary);
  let salaryScore = 0;
  if (salaryNum >= 5000) salaryScore = 25;
  else if (salaryNum >= 3000) salaryScore = 15;
  else if (j.salary && j.salary.trim()) salaryScore = 10;

  const score = taiwanScore + asyncScore + roleScore + salaryScore;

  // Final one-sentence rule check
  const oneshotPass = (eligible === 'yes' || eligible === 'unclear') && asyncLevel !== 'incompatible' && j.location_risk !== 'high';

  let decision;
  if (!oneshotPass || score < 70) decision = 'reject';
  else if (score >= 85) decision = 'immediate_apply';
  else decision = 'keep';

  // Why it fits Jerry
  const whyFit = [
    roleCategory !== 'other' ? `Role matches: ${roleCategory}` : null,
    asyncLevel === 'high' || asyncLevel === 'medium' ? `Async-friendly (${asyncLevel})` : null,
    eligible === 'yes' ? 'Taiwan eligible confirmed' : eligible === 'unclear' ? 'Taiwan eligibility unclear - manual check' : null,
    j.timezone_risk === 'low' ? 'Low timezone risk' : null,
    salaryNum >= 3000 ? `Salary ${j.salary}` : null
  ].filter(Boolean).join(' | ');

  return {
    json: {
      ...j,
      async_level: asyncLevel,
      async_score: asyncScore,
      role_category: roleCategory,
      role_score: roleScore,
      taiwan_score: taiwanScore,
      salary_score: salaryScore,
      score,
      decision,
      why_good_fit: whyFit,
      application_status: decision === 'immediate_apply' ? 'To Apply' : decision === 'keep' ? 'Saved' : 'Rejected'
    }
  };
});

const all = $input.all().map(i => i.json);
const kept = all.filter(j => j.decision !== 'reject').sort((a,b) => b.score - a.score);
const rejected = all.filter(j => j.decision === 'reject');
const topJobs = kept.slice(0, 10);
const manual = kept.filter(j => j.taiwan_eligible === 'unclear' && j.score >= 70);

const rejectedByReason = {};
for (const j of rejected) {
  const r = j.rejection_reason || 'other';
  rejectedByReason[r] = (rejectedByReason[r] || 0) + 1;
}

const today = new Date().toLocaleDateString('en-US', { timeZone: 'Asia/Taipei', weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

let html = `<h2>🌏 Daily Taiwan Eligible Async Remote Jobs</h2><p><strong>${today} | Asia/Taipei</strong></p>`;
html += `<p>Found <strong>${kept.length}</strong> eligible jobs today. ${kept.filter(j=>j.score>=85).length} are high-priority (score ≥ 85).</p><hr>`;

if (topJobs.length === 0) {
  html += '<p>No eligible jobs found today. Filters were strict — try again tomorrow.</p>';
} else {
  html += '<h3>🔥 Top Jobs Today</h3>';
  topJobs.forEach((j, i) => {
    const badge = j.score >= 85 ? '🔥' : j.score >= 75 ? '✅' : '👀';
    html += `<div style="border:1px solid #ddd;padding:12px;margin:8px 0;border-radius:6px">`;
    html += `<h4>${badge} ${i+1}. <a href="${j.job_url}">${j.job_title}</a></h4>`;
    html += `<p><strong>Company:</strong> ${j.company}<br>`;
    html += `<strong>Score:</strong> ${j.score}/100<br>`;
    html += `<strong>Taiwan eligible:</strong> ${j.taiwan_eligible} — ${j.taiwan_reason}<br>`;
    html += `<strong>Async level:</strong> ${j.async_level}<br>`;
    html += `<strong>Timezone risk:</strong> ${j.timezone_risk}<br>`;
    html += `<strong>Salary:</strong> ${j.salary || 'Not listed'}<br>`;
    html += `<strong>Why it fits Jerry:</strong> ${j.why_good_fit}</p>`;
    html += `<a href="${j.job_url}" style="background:#0070f3;color:white;padding:6px 12px;text-decoration:none;border-radius:4px">Apply Now</a>`;
    html += `</div>`;
  });
}

if (manual.length > 0) {
  html += '<h3>⚠️ Manual Check Needed</h3><ul>';
  manual.forEach(j => { html += `<li><a href="${j.job_url}">${j.job_title}</a> @ ${j.company} — Score: ${j.score} — ${j.taiwan_reason}</li>`; });
  html += '</ul>';
}

html += '<h3>📊 Rejected Summary</h3><ul>';
for (const [reason, count] of Object.entries(rejectedByReason)) {
  html += `<li>${count} rejected: ${reason}</li>`;
}
html += `<li>${rejected.filter(j=>j.score<70).length} rejected: score below 70</li>`;
html += '</ul>';

// Plain text for Telegram top job
const top = topJobs[0];
const telegramText = top
  ? `🔥 Top job today: ${top.job_title} @ ${top.company}\nScore: ${top.score}/100 | Taiwan: ${top.taiwan_eligible}\nAsync: ${top.async_level} | Salary: ${top.salary||'n/a'}\n${top.job_url}`
  : 'No high-eligibility jobs found today.';

const alertJobs = kept.filter(j => j.score >= 85);

return [{
  json: {
    digest_html: html,
    digest_subject: `[Job Hunter] ${kept.length} Taiwan-eligible jobs today — ${kept.filter(j=>j.score>=85).length} high priority`,
    telegram_message: telegramText,
    all_scored_jobs: all,
    kept_jobs: kept,
    alert_jobs: alertJobs,
    total_kept: kept.length,
    total_rejected: rejected.length
  }
}];

const prevJob = $('Score ≥ 85?').first().json;
const aiRaw = $input.first().json;
const coverLetter = aiRaw?.content?.[0]?.text || 'Cover letter generation failed.';
return [{
  json: {
    ...prevJob,
    cover_letter: coverLetter
  }
}];

